            530 => 
            array (
                'id' => 1531,
                'bitrix_id' => '1972',
                'task_id' => 191,
                'author_id' => '1',
                'author_name' => 'Phạm Ngọc Sơn',
                'message' => NULL,
                'post_message' => 'Gửi Diệp, về bài viết của em vừa rồi, anh có mấy ý kiến như sau:
- Vì vậy mặc dù trong câu đầu tiên rất vô nghĩa
- Đã tham khảo nguồn ở đâu, trích dẫn
- Bài viêt là nâng cấp thang máy nhưng dường như đang nói về bảo trì, nâng cấp thì có nhiều cấp độ hơn: Thay thế các linh kiện, Thay thế hoặc nâng cấp thiết bị, Hiện đại hóa đa thiết bị và giải pháp, Thay thế hoàn toàn một thang máy mới, Đồng bộ hóa dịch vụ [URL=https://tapchithangmay.vn/giai-phap-nang-cap-thang-may-nao-phu-hop-cho-ban/]https://tapchithangmay.vn/giai-phap-nang-cap-thang-may-nao-phu-hop-cho-ban/[/URL]
- Bố cục bài viết là gì, mô hình nào
- Đoạn 1 tập trung nói về vấn đề gì
- Logo nếu nền quá tối thì có thể bỏ chữ dưới chân logo đi',
                'raw_data' => '{"ID": "1972", "AUTHOR_ID": "1", "POST_DATE": "2022-09-08T07:34:35+03:00", "AUTHOR_NAME": "Phạm Ngọc Sơn", "AUTHOR_EMAIL": "", "POST_MESSAGE": "Gửi Diệp, về bài viết của em vừa rồi, anh có mấy ý kiến như sau:\\n- Vì vậy mặc dù trong câu đầu tiên rất vô nghĩa\\n- Đã tham khảo nguồn ở đâu, trích dẫn\\n- Bài viêt là nâng cấp thang máy nhưng dường như đang nói về bảo trì, nâng cấp thì có nhiều cấp độ hơn: Thay thế các linh kiện, Thay thế hoặc nâng cấp thiết bị, Hiện đại hóa đa thiết bị và giải pháp, Thay thế hoàn toàn một thang máy mới, Đồng bộ hóa dịch vụ [URL=https://tapchithangmay.vn/giai-phap-nang-cap-thang-may-nao-phu-hop-cho-ban/]https://tapchithangmay.vn/giai-phap-nang-cap-thang-may-nao-phu-hop-cho-ban/[/URL]\\n- Bố cục bài viết là gì, mô hình nào\\n- Đoạn 1 tập trung nói về vấn đề gì\\n- Logo nếu nền quá tối thì có thể bỏ chữ dưới chân logo đi", "POST_MESSAGE_HTML": null}',
