            549 => 
            array (
                'id' => 1550,
                'bitrix_id' => '1858',
                'task_id' => 190,
                'author_id' => '1',
                'author_name' => 'Phạm Ngọc Sơn',
                'message' => NULL,
                'post_message' => 'Gửi Diệp, anh có mấy ý kiến như sau: 
- Như đã trao đổi với em, công việc chính của em sẽ là quản lý Facebook và content cho khách hàng
- Anh đồng ý với các chủ đề em đề xuất chủ đề em đã viết, em cần viết rõ cụ thể hơn em sẽ viết cái gì, và định dùng hình ảnh gì cho từng bài viết đó. Em có thể sử dụng facebook sudio sáng tạo để lên lịch bài viết nhưng tối thiểu em phải gửi tin trên bitrix24 hoặc zalo để chắc chắn anh biết là bài viết đã lên hoặc là em cho anh ngày giờ để anh xem vào một mốc cố định. Hạn cuối cho bài đầu tiên là thứ 4, ngày 7/9/2022
- 4 bài viết cần được viết theo cấu trúc nhất định, anh sẽ hỏi và em cần phân tích được. Anh nghĩ AIDA là sự lựa chọn hợp lý trước khi triển khai các bố cục khác.  Họp tháng 7 đã trao đổi về vấn đề triển khai AIDA, anh yêu cầu cả 4 bài viết em đề xuất phải triển khai hết. Có thể tham khảo: [URL=https://nokamarketing.com/tong-hop-mo-hinh-content-marketing]https://nokamarketing.com/tong-hop-mo-hinh-content-marketing[/URL] 
- phải kiểm tra tương thích của ảnh trên thiết bị di động - thiết bị truy cập chính của khách hàng 
- Về hình ảnh, em cần chủ động nâng cao năng lực của mình trong công tác chỉnh sửa ảnh bằng bất kì phần mềm nào em thấy hợp lý. Em có thể dùng template những cũng cần sửa nó cho phù hợp với nhu cầu của em. Năm nay bằng khen, hình ảnh,... của công ty em phải chủ động, anh đã báo trước từ bây giờ là rất sớm
Trân trọng!',
                'raw_data' => '{"ID": "1858", "AUTHOR_ID": "1", "POST_DATE": "2022-09-05T06:37:15+03:00", "AUTHOR_NAME": "Phạm Ngọc Sơn", "AUTHOR_EMAIL": "", "POST_MESSAGE": "Gửi Diệp, anh có mấy ý kiến như sau: \\n- Như đã trao đổi với em, công việc chính của em sẽ là quản lý Facebook và content cho khách hàng\\n- Anh đồng ý với các chủ đề em đề xuất chủ đề em đã viết, em cần viết rõ cụ thể hơn em sẽ viết cái gì, và định dùng hình ảnh gì cho từng bài viết đó. Em có thể sử dụng facebook sudio sáng tạo để lên lịch bài viết nhưng tối thiểu em phải gửi tin trên bitrix24 hoặc zalo để chắc chắn anh biết là bài viết đã lên hoặc là em cho anh ngày giờ để anh xem vào một mốc cố định. Hạn cuối cho bài đầu tiên là thứ 4, ngày 7/9/2022\\n- 4 bài viết cần được viết theo cấu trúc nhất định, anh sẽ hỏi và em cần phân tích được. Anh nghĩ AIDA là sự lựa chọn hợp lý trước khi triển khai các bố cục khác.  Họp tháng 7 đã trao đổi về vấn đề triển khai AIDA, anh yêu cầu cả 4 bài viết em đề xuất phải triển khai hết. Có thể tham khảo: [URL=https://nokamarketing.com/tong-hop-mo-hinh-content-marketing]https://nokamarketing.com/tong-hop-mo-hinh-content-marketing[/URL] \\n- phải kiểm tra tương thích của ảnh trên thiết bị di động - thiết bị truy cập chính của khách hàng \\n- Về hình ảnh, em cần chủ động nâng cao năng lực của mình trong công tác chỉnh sửa ảnh bằng bất kì phần mềm nào em thấy hợp lý. Em có thể dùng template những cũng cần sửa nó cho phù hợp với nhu cầu của em. Năm nay bằng khen, hình ảnh,... của công ty em phải chủ động, anh đã báo trước từ bây giờ là rất sớm\\nTrân trọng!", "POST_MESSAGE_HTML": null}',
